/**
 * A Ralph Loop Agent implements the "Ralph Wiggum" technique - an iterative
 * approach that continuously runs until a task is completed.
 *
 * The agent has two nested loops:
 * 1. **Outer loop (Ralph loop)**: Runs iterations until verifyCompletion returns true
 * 2. **Inner loop (Tool loop)**: Executes tools and LLM calls within each iteration
 *
 * @example
 * ```typescript
 * const agent = new RalphLoopAgent({
 *   model: 'anthropic/claude-opus-4.5',
 *   instructions: 'You are a helpful assistant.',
 *   tools: { readFile, writeFile },
 *   stopWhen: iterationCountIs(10),
 *   verifyCompletion: async ({ result }) => ({
 *     complete: result.text.includes('DONE'),
 *     reason: 'Task completed',
 *   }),
 * });
 *
 * const result = await agent.loop({ prompt: 'Do the task' });
 * ```
 */
export class RalphLoopAgent<TOOLS extends ToolSet = {}> {
  readonly version = 'ralph-agent-v1';

  private readonly settings: RalphLoopAgentSettings<TOOLS>;
  private readonly contextManager: RalphContextManager | null;

  constructor(settings: RalphLoopAgentSettings<TOOLS>) {
    this.settings = settings;

    // Initialize context manager if configured
    this.contextManager = settings.contextManagement
      ? new RalphContextManager(settings.contextManagement)
      : null;
  }

  /**
   * Get the context manager (if enabled).
   */
  getContextManager(): RalphContextManager | null {
    return this.contextManager;
  }

  /**
   * The id of the agent.
   */
  get id(): string | undefined {
    return this.settings.id;
  }

  /**
   * The tools that the agent can use.
   */
  get tools(): TOOLS {
    return this.settings.tools as TOOLS;
  }

  /**
   * Get the model identifier string.
   */
  private getModelId(): string {
    const model = this.settings.model;
    // Handle both string models (gateway format) and LanguageModel objects
    if (typeof model === 'string') {
      return model;
    }
    return model.modelId ?? 'unknown';
  }

  /**
   * Check if the current model is an Anthropic model (for prompt caching).
   */
  private isAnthropicModel(): boolean {
    const model = this.settings.model;
    if (typeof model === 'string') {
      return model.includes('anthropic') || model.includes('claude');
    }
    return (
      model.provider === 'anthropic' ||
      model.provider?.includes('anthropic') ||
      model.modelId?.includes('anthropic') ||
      model.modelId?.includes('claude')
    );
  }

  /**
   * Get the stop conditions as an array.
   */
  private getStopConditions(): Array<RalphStopCondition<TOOLS>> {
    const stopWhen = this.settings.stopWhen;
    if (!stopWhen) {
      return [iterationCountIs(10)]; // default
    }
    return Array.isArray(stopWhen) ? stopWhen : [stopWhen];
  }

  /**
   * Create an empty usage object.
   */
  private createEmptyUsage(): LanguageModelUsage {
    return {
      inputTokens: 0,
      inputTokenDetails: {
        noCacheTokens: undefined,
        cacheReadTokens: undefined,
        cacheWriteTokens: undefined,
      },
      outputTokens: 0,
      outputTokenDetails: {
        textTokens: undefined,
        reasoningTokens: undefined,
      },
      totalTokens: 0,
    };
  }

  /**
   * Runs the agent loop until completion or stop condition is met.
   */
  async loop({
    prompt,
    abortSignal,
    preserveContext = false,
    startIteration = 0,
  }: RalphLoopAgentCallParameters): Promise<RalphLoopAgentResult<TOOLS>> {
    const allResults: Array<GenerateTextResult<TOOLS, never>> = [];
    let currentMessages: Array<ModelMessage> = [];
    let iteration = startIteration;
    let totalUsage: LanguageModelUsage = this.createEmptyUsage();
    let completionReason: RalphLoopAgentResult<TOOLS>['completionReason'] = 'max-iterations';
    let reason: string | undefined;

    const stopConditions = this.getStopConditions();
    const modelId = this.getModelId();
    const model = this.settings.model;

    // Reset context manager for new loop (unless preserving context for resume)
    if (!preserveContext) {
      this.contextManager?.clear();
    }

    // Build the initial user message
    const initialUserMessage: ModelMessage = {
      role: 'user',
      content: [{ type: 'text', text: prompt }],
    };

    // Add instructions as system message if provided
    const systemMessages = this.buildSystemMessages();

    // Loop until stop condition is met
    while (true) {
      // Check for abort
      if (abortSignal?.aborted) {
        completionReason = 'aborted';
        break;
      }

      iteration++;
      const startTime = Date.now();

      // Call onIterationStart
      await this.settings.onIterationStart?.({ iteration });

      // Prepare messages with context management
      let messagesToSend: Array<ModelMessage>;
      let summarized = false;

      if (this.contextManager) {
        // Use context manager to prepare messages
        const prepared = await this.contextManager.prepareMessagesForIteration(
          currentMessages,
          iteration,
          model,
          allResults[allResults.length - 1]
        );

        messagesToSend = [
          ...systemMessages,
          initialUserMessage,
          ...prepared.messages,
        ];
        summarized = prepared.summarized;

        // If we summarized, notify
        if (summarized && this.settings.onContextSummarized) {
          const budget = this.contextManager.getTokenBudget();
          await this.settings.onContextSummarized({
            iteration,
            summarizedIterations: iteration - (this.settings.contextManagement?.recentIterationsToKeep ?? 2),
            tokensSaved: budget.available,
          });
        }

        // Add context injection (summaries, change log)
        const contextInjection = this.contextManager.buildContextInjection();
        if (contextInjection) {
          // Append to last system message or create new one
          if (systemMessages.length > 0) {
            const lastSystem = messagesToSend.find(m => m.role === 'system');
            if (lastSystem && typeof lastSystem.content === 'string') {
              lastSystem.content += contextInjection;
            }
          } else {
            messagesToSend.unshift({
              role: 'system',
              content: contextInjection,
            });
          }
        }
      } else {
        // No context management - use messages as-is
        messagesToSend = [
          ...systemMessages,
          initialUserMessage,
          ...currentMessages,
        ];
      }

      // If not the first iteration, add continuation prompt
      if (iteration > 1) {
        messagesToSend.push({
          role: 'user',
          content: [
            {
              type: 'text',
              text: 'Continue working on the task. The previous attempt was not complete.',
            },
          ],
        });
      }

      // Estimate tokens before sending (for debugging/monitoring)
      if (this.contextManager) {
        const estimatedTokens = messagesToSend.reduce(
          (sum, m) => sum + estimateMessageTokens(m),
          0
        );
        const budget = this.contextManager.getTokenBudget();

        // Log warning if approaching limit
        if (estimatedTokens > budget.total * 0.9) {
          console.warn(
            `[RalphLoopAgent] Warning: Estimated ${estimatedTokens} tokens, approaching limit of ${budget.total}`
          );
        }
      }

      // Create prepareStep that adds cache control for Anthropic models
      const isAnthropic = this.isAnthropicModel();
      const userPrepareStep = this.settings.prepareStep;

      // Helper to add cache control to last message
      const addCacheControlToMessages = (messages: ModelMessage[]): ModelMessage[] => {
        if (messages.length === 0) return messages;

        return messages.map((message: ModelMessage, index: number) => {
          if (index === messages.length - 1) {
            return {
              ...message,
              providerOptions: {
                ...message.providerOptions,
                anthropic: {
                  ...(message.providerOptions?.anthropic as Record<string, unknown> ?? {}),
                  cacheControl: { type: 'ephemeral' },
                },
              },
            };
          }
          return message;
        });
      };

      const prepareStepWithCaching: typeof userPrepareStep = isAnthropic
        ? async (stepInfo) => {
            // First apply user's prepareStep if provided
            const userResult = userPrepareStep ? await userPrepareStep(stepInfo) : {};
            const messages = userResult?.messages ?? stepInfo.messages;

            // Add cache control to the last message for Anthropic
            const cacheControlMessages = addCacheControlToMessages(messages);
            return { ...userResult, messages: cacheControlMessages };
          }
        : userPrepareStep;

      // Run the inner tool loop
      const result = (await generateText({
        model: this.settings.model,
        messages: messagesToSend,
        tools: this.settings.tools,
        toolChoice: this.settings.toolChoice,
        stopWhen: this.settings.toolStopWhen ?? stepCountIs(20),
        maxOutputTokens: this.settings.maxOutputTokens,
        temperature: this.settings.temperature,
        topP: this.settings.topP,
        topK: this.settings.topK,
        presencePenalty: this.settings.presencePenalty,
        frequencyPenalty: this.settings.frequencyPenalty,
        stopSequences: this.settings.stopSequences,
        seed: this.settings.seed,
        experimental_telemetry: this.settings.experimental_telemetry,
        activeTools: this.settings.activeTools,
        prepareStep: prepareStepWithCaching,
        experimental_repairToolCall: this.settings.experimental_repairToolCall,
        providerOptions: this.settings.providerOptions,
        experimental_context: this.settings.experimental_context,
        abortSignal,
      })) as GenerateTextResult<TOOLS, never>;

      allResults.push(result);

      // Update total usage - aggregate from steps for more accurate counts
      const iterationUsage = aggregateStepUsage(result);
      totalUsage = addLanguageModelUsage(totalUsage, iterationUsage);

      // Add the response messages to conversation history
      currentMessages = [...currentMessages, ...result.response.messages];

      const duration = Date.now() - startTime;

      // Call onIterationEnd
      await this.settings.onIterationEnd?.({
        iteration,
        duration,
        result,
      });

      // Check stop conditions AFTER running iteration
      const stopContext: RalphStopConditionContext<TOOLS> = {
        iteration,
        allResults,
        totalUsage,
        model: modelId,
      };

      if (await isRalphStopConditionMet({ stopConditions, context: stopContext })) {
        completionReason = 'max-iterations';
        break;
      }

      // Verify completion
      if (this.settings.verifyCompletion) {
        const verification = await this.settings.verifyCompletion({
          result,
          iteration,
          allResults,
          originalPrompt: prompt,
        });

        if (verification.complete) {
          completionReason = 'verified';
          reason = verification.reason;
          break;
        }

        // If verification provides feedback, add it
        if (verification.reason && !verification.complete) {
          currentMessages.push({
            role: 'user',
            content: [
              {
                type: 'text',
                text: `Feedback: ${verification.reason}`,
              },
            ],
          });

          // Track feedback in context manager
          this.contextManager?.addChangeLogEntry({
            type: 'observation',
            summary: 'Verification feedback received',
            details: verification.reason.slice(0, 200),
          });
        }
      }
    }

    const finalResult = allResults[allResults.length - 1]!;

    return {
      text: finalResult.text,
      iterations: iteration,
      completionReason,
      reason,
      result: finalResult,
      allResults,
      totalUsage,
    };
  }

  /**
   * Streams the agent loop. Streams only the final iteration.
   * For full control, use loop() with callbacks instead.
   */
  async stream({
    prompt,
    abortSignal,
  }: RalphLoopAgentCallParameters): Promise<StreamTextResult<TOOLS, never>> {
    const allResults: Array<GenerateTextResult<TOOLS, never>> = [];
    let currentMessages: Array<ModelMessage> = [];
    let iteration = 0;
    let totalUsage: LanguageModelUsage = this.createEmptyUsage();

    const stopConditions = this.getStopConditions();
    const modelId = this.getModelId();

    const initialUserMessage: ModelMessage = {
      role: 'user',
      content: [{ type: 'text', text: prompt }],
    };

    const systemMessages = this.buildSystemMessages();

    // Run non-streaming iterations until we should stream the final one
    while (true) {
      if (abortSignal?.aborted) {
        break;
      }

      iteration++;

      // Check if THIS iteration would be the last (next would hit stop condition)
      const nextStopContext: RalphStopConditionContext<TOOLS> = {
        iteration: iteration + 1,
        allResults,
        totalUsage,
        model: modelId,
      };

      // If next iteration would stop, stream this one instead
      if (await isRalphStopConditionMet({ stopConditions, context: nextStopContext })) {
        break;
      }

      const startTime = Date.now();

      await this.settings.onIterationStart?.({ iteration });

      const messages: Array<ModelMessage> = [
        ...systemMessages,
        initialUserMessage,
        ...currentMessages,
      ];

      if (iteration > 1) {
        messages.push({
          role: 'user',
          content: [
            {
              type: 'text',
              text: 'Continue working on the task. The previous attempt was not complete.',
            },
          ],
        });
      }

      const result = (await generateText({
        model: this.settings.model,
        messages,
        tools: this.settings.tools,
        toolChoice: this.settings.toolChoice,
        stopWhen: this.settings.toolStopWhen ?? stepCountIs(20),
        maxOutputTokens: this.settings.maxOutputTokens,
        temperature: this.settings.temperature,
        topP: this.settings.topP,
        topK: this.settings.topK,
        presencePenalty: this.settings.presencePenalty,
        frequencyPenalty: this.settings.frequencyPenalty,
        stopSequences: this.settings.stopSequences,
        seed: this.settings.seed,
        experimental_telemetry: this.settings.experimental_telemetry,
        activeTools: this.settings.activeTools,
        prepareStep: this.settings.prepareStep,
        experimental_repairToolCall: this.settings.experimental_repairToolCall,
        providerOptions: this.settings.providerOptions,
        experimental_context: this.settings.experimental_context,
        abortSignal,
      })) as GenerateTextResult<TOOLS, never>;

      allResults.push(result);
      const iterationUsage = aggregateStepUsage(result);
      totalUsage = addLanguageModelUsage(totalUsage, iterationUsage);
      currentMessages = [...currentMessages, ...result.response.messages];

      const duration = Date.now() - startTime;
      await this.settings.onIterationEnd?.({ iteration, duration, result });

      if (this.settings.verifyCompletion) {
        const verification = await this.settings.verifyCompletion({
          result,
          iteration,
          allResults,
          originalPrompt: prompt,
        });

        if (verification.complete) {
          // Complete early - return a stream for the final message
          return streamText({
            model: this.settings.model,
            messages: [...systemMessages, initialUserMessage, ...currentMessages],
            tools: this.settings.tools,
            toolChoice: this.settings.toolChoice,
            stopWhen: this.settings.toolStopWhen ?? stepCountIs(20),
            maxOutputTokens: this.settings.maxOutputTokens,
            temperature: this.settings.temperature,
            abortSignal,
          }) as StreamTextResult<TOOLS, never>;
        }

        if (verification.reason) {
          currentMessages.push({
            role: 'user',
            content: [{ type: 'text', text: `Feedback: ${verification.reason}` }],
          });
        }
      }
    }

    // Stream the final iteration
    iteration++;
    const finalMessages: Array<ModelMessage> = [
      ...systemMessages,
      initialUserMessage,
      ...currentMessages,
    ];

    if (iteration > 1) {
      finalMessages.push({
        role: 'user',
        content: [
          {
            type: 'text',
            text: 'Continue working on the task. The previous attempt was not complete.',
          },
        ],
      });
    }

    return streamText({
      model: this.settings.model,
      messages: finalMessages,
      tools: this.settings.tools,
      toolChoice: this.settings.toolChoice,
      stopWhen: this.settings.toolStopWhen ?? stepCountIs(20),
      maxOutputTokens: this.settings.maxOutputTokens,
      temperature: this.settings.temperature,
      topP: this.settings.topP,
      topK: this.settings.topK,
      presencePenalty: this.settings.presencePenalty,
      frequencyPenalty: this.settings.frequencyPenalty,
      stopSequences: this.settings.stopSequences,
      seed: this.settings.seed,
      experimental_telemetry: this.settings.experimental_telemetry,
      activeTools: this.settings.activeTools,
      prepareStep: this.settings.prepareStep,
      experimental_repairToolCall: this.settings.experimental_repairToolCall,
      providerOptions: this.settings.providerOptions,
      experimental_context: this.settings.experimental_context,
      abortSignal,
    }) as StreamTextResult<TOOLS, never>;
  }

  /**
   * Build system messages from instructions.
   */
  private buildSystemMessages(): Array<ModelMessage> {
    const { instructions } = this.settings;

    if (!instructions) {
      return [];
    }

    if (typeof instructions === 'string') {
      return [{ role: 'system', content: instructions }];
    }

    if (Array.isArray(instructions)) {
      return instructions;
    }

    return [instructions];
  }
}

import type { ModelMessage, AssistantModelMessage, ToolResultPart } from '@ai-sdk/provider-utils';
import type { LanguageModel, GenerateTextResult, ToolSet } from 'ai';
import { generateText } from 'ai';

/**
 * Configuration for context management.
 */
export interface RalphContextConfig {
  /**
   * Maximum tokens to use for context (default: 150,000 - leaves room for output).
   * Set to match your model's context window minus output buffer.
   */
  maxContextTokens?: number;

  /**
   * Token budget reserved for the change log (default: 5,000).
   */
  changeLogBudget?: number;

  /**
   * Token budget reserved for file context (default: 50,000).
   */
  fileContextBudget?: number;

  /**
   * Maximum characters for a single file read before truncation (default: 30,000).
   * Files larger than this will be chunked with line numbers.
   */
  maxFileChars?: number;

  /**
   * Whether to enable auto-summarization of older messages.
   */
  enableSummarization?: boolean;

  /**
   * Number of recent iterations to keep in full detail (default: 2).
   */
  recentIterationsToKeep?: number;

  /**
   * Model to use for summarization (optional, uses main model if not provided).
   */
  summarizationModel?: LanguageModel;
}

/**
 * A tracked file in context.
 */
export interface TrackedFile {
  path: string;
  content: string;
  estimatedTokens: number;
  lastAccessed: number;
  /** If the file was chunked, this is the line range */
  lineRange?: { start: number; end: number };
}

/**
 * A change log entry.
 */
export interface ChangeLogEntry {
  timestamp: number;
  iteration: number;
  type: 'decision' | 'action' | 'error' | 'observation';
  summary: string;
  /** Optional details (will be truncated if too long) */
  details?: string;
}

/**
 * Summary of a previous iteration.
 */
export interface IterationSummary {
  iteration: number;
  summary: string;
  toolsUsed: string[];
  filesModified: string[];
  estimatedTokens: number;
}

/**
 * Rough token estimation (4 chars ≈ 1 token for English text).
 * This is intentionally conservative.
 */
export function estimateTokens(text: string): number {
  return Math.ceil(text.length / 3.5);
}

/**
 * Estimate tokens for a ModelMessage.
 */
export function estimateMessageTokens(message: ModelMessage): number {
  if (typeof message.content === 'string') {
    return estimateTokens(message.content);
  }
  if (Array.isArray(message.content)) {
    return message.content.reduce((sum, part) => {
      if ('text' in part && typeof part.text === 'string') {
        return sum + estimateTokens(part.text);
      }
      if ('result' in part) {
        const result = typeof part.result === 'string' 
          ? part.result 
          : JSON.stringify(part.result);
        return sum + estimateTokens(result);
      }
      return sum + 100; // Default estimate for other parts
    }, 0);
  }
  return 100;
}

/**
 * Manages context for long-running agent loops.
 * 
 * Tracks:
 * - File context (recently accessed files)
 * - Change log (decisions and actions)
 * - Message history (with optional summarization)
 */
export class RalphContextManager {
  private config: Required<Omit<RalphContextConfig, 'summarizationModel'>> & 
    Pick<RalphContextConfig, 'summarizationModel'>;

  private trackedFiles: Map<string, TrackedFile> = new Map();
  private changeLog: ChangeLogEntry[] = [];
  private iterationSummaries: IterationSummary[] = [];
  private currentIteration: number = 0;

  constructor(config: RalphContextConfig = {}) {
    this.config = {
      maxContextTokens: config.maxContextTokens ?? 150_000,
      changeLogBudget: config.changeLogBudget ?? 5_000,
      fileContextBudget: config.fileContextBudget ?? 50_000,
      maxFileChars: config.maxFileChars ?? 30_000,
      enableSummarization: config.enableSummarization ?? true,
      recentIterationsToKeep: config.recentIterationsToKeep ?? 2,
      summarizationModel: config.summarizationModel,
    };
  }

  /**
   * Get the current token budget status.
   */
  getTokenBudget(): {
    total: number;
    used: {
      files: number;
      changeLog: number;
      summaries: number;
    };
    available: number;
  } {
    const filesTokens = Array.from(this.trackedFiles.values())
      .reduce((sum, f) => sum + f.estimatedTokens, 0);

    const changeLogTokens = this.changeLog
      .reduce((sum, e) => sum + estimateTokens(e.summary) + estimateTokens(e.details ?? ''), 0);

    const summariesTokens = this.iterationSummaries
      .reduce((sum, s) => sum + s.estimatedTokens, 0);

    const used = filesTokens + changeLogTokens + summariesTokens;

    return {
      total: this.config.maxContextTokens,
      used: {
        files: filesTokens,
        changeLog: changeLogTokens,
        summaries: summariesTokens,
      },
      available: this.config.maxContextTokens - used,
    };
  }

  /**
   * Set the current iteration number.
   */
  setIteration(iteration: number): void {
    this.currentIteration = iteration;
  }

  /**
   * Track a file being read. Returns the content (potentially truncated).
   */
  trackFileRead(
    path: string, 
    content: string,
    options?: {
      /** Specific line range to read */
      lineRange?: { start: number; end: number };
      /** Force refresh even if cached */
      refresh?: boolean;
    }
  ): {
    content: string;
    truncated: boolean;
    totalLines?: number;
    lineRange?: { start: number; end: number };
  } {
    const existing = this.trackedFiles.get(path);

    // If cached and not refreshing, just update access time
    if (existing && !options?.refresh && !options?.lineRange) {
      existing.lastAccessed = Date.now();
      return {
        content: existing.content,
        truncated: existing.lineRange !== undefined,
        lineRange: existing.lineRange,
      };
    }

    // Handle large files
    const lines = content.split('\n');
    let finalContent = content;
    let lineRange = options?.lineRange;
    let truncated = false;

    if (content.length > this.config.maxFileChars) {
      if (options?.lineRange) {
        // Extract specific range
        const { start, end } = options.lineRange;
        const selectedLines = lines.slice(start - 1, end);
        finalContent = selectedLines
          .map((line, i) => `${String(start + i).padStart(6)}| ${line}`)
          .join('\n');
        lineRange = { start, end };
      } else {
        // Auto-truncate: show first part with line numbers
        const maxLines = Math.floor(this.config.maxFileChars / 80);
        const selectedLines = lines.slice(0, maxLines);
        finalContent = selectedLines
          .map((line, i) => `${String(i + 1).padStart(6)}| ${line}`)
          .join('\n');
        finalContent += `\n\n... [TRUNCATED: File has ${lines.length} lines, showing 1-${maxLines}. Use lineRange to read specific sections] ...`;
        lineRange = { start: 1, end: maxLines };
        truncated = true;
      }
    }

    const estimatedTokens = estimateTokens(finalContent);

    // Evict old files if over budget
    this.evictFilesIfNeeded(estimatedTokens);

    this.trackedFiles.set(path, {
      path,
      content: finalContent,
      estimatedTokens,
      lastAccessed: Date.now(),
      lineRange,
    });

    return {
      content: finalContent,
      truncated,
      totalLines: lines.length,
      lineRange,
    };
  }

  /**
   * Track a file being written/modified.
   */
  trackFileWrite(path: string, content: string): void {
    // Remove from tracked files (content has changed)
    this.trackedFiles.delete(path);

    // Add to change log
    this.addChangeLogEntry({
      type: 'action',
      summary: `Modified file: ${path}`,
      details: `Wrote ${content.length} chars`,
    });
  }

  /**
   * Track a file edit (search/replace style).
   */
  trackFileEdit(path: string, oldString: string, newString: string): void {
    // Update cached file if present
    const existing = this.trackedFiles.get(path);
    if (existing) {
      existing.content = existing.content.replace(oldString, newString);
      existing.estimatedTokens = estimateTokens(existing.content);
      existing.lastAccessed = Date.now();
    }

    // Add to change log
    this.addChangeLogEntry({
      type: 'action',
      summary: `Edited file: ${path}`,
      details: `Replaced "${oldString.slice(0, 50)}${oldString.length > 50 ? '...' : ''}" with "${newString.slice(0, 50)}${newString.length > 50 ? '...' : ''}"`,
    });
  }

  /**
   * Add an entry to the change log.
   */
  addChangeLogEntry(entry: Omit<ChangeLogEntry, 'timestamp' | 'iteration'>): void {
    this.changeLog.push({
      ...entry,
      timestamp: Date.now(),
      iteration: this.currentIteration,
    });

    // Trim change log if over budget
    this.trimChangeLog();
  }

  /**
   * Get the change log as a formatted string for context.
   */
  getChangeLogContext(): string {
    if (this.changeLog.length === 0) {
      return '';
    }

    const header = '## Change Log (Recent Decisions & Actions)\n\n';
    const entries = this.changeLog.map(e => {
      const icon = e.type === 'decision' ? '📋' : 
                   e.type === 'action' ? '✅' :
                   e.type === 'error' ? '❌' : '👁️';
      return `- [Iter ${e.iteration}] ${icon} ${e.summary}${e.details ? ` (${e.details})` : ''}`;
    }).join('\n');

    return header + entries;
  }

  /**
   * Get tracked files context.
   */
  getFileContext(): string {
    if (this.trackedFiles.size === 0) {
      return '';
    }

    const header = '## Files in Context\n\n';
    const files = Array.from(this.trackedFiles.values())
      .sort((a, b) => b.lastAccessed - a.lastAccessed)
      .map(f => {
        const rangeInfo = f.lineRange 
          ? ` (lines ${f.lineRange.start}-${f.lineRange.end})`
          : '';
        return `### ${f.path}${rangeInfo}\n\`\`\`\n${f.content}\n\`\`\``;
      })
      .join('\n\n');

    return header + files;
  }

  /**
   * Summarize an iteration's messages for future context.
   */
  async summarizeIteration(
    iteration: number,
    messages: ModelMessage[],
    model: LanguageModel
  ): Promise<IterationSummary> {
    // Extract tool calls and results
    const toolsUsed: string[] = [];
    const filesModified: string[] = [];

    for (const msg of messages) {
      if (msg.role === 'assistant' && Array.isArray(msg.content)) {
        for (const part of msg.content) {
          if ('toolName' in part) {
            toolsUsed.push((part as { toolName: string }).toolName);
            const toolName = (part as { toolName: string }).toolName;
            if (toolName === 'writeFile' || toolName === 'editFile') {
              // Handle both 'args' and 'input' property names
              const args = ('args' in part ? part.args : 'input' in part ? (part as any).input : null) as Record<string, unknown> | null;
              if (args?.path || args?.filePath) {
                filesModified.push((args.path || args.filePath) as string);
              }
            }
          }
        }
      }
    }

    // Generate a summary using the model
    const messagesText = messages.map(m => {
      if (typeof m.content === 'string') return m.content;
      return JSON.stringify(m.content).slice(0, 500);
    }).join('\n');

    let summary: string;

    try {
      const result = await generateText({
        model: this.config.summarizationModel ?? model,
        messages: [
          {
            role: 'system',
            content: 'Summarize this agent iteration in 2-3 concise sentences. Focus on: what was accomplished, key decisions made, and any blockers encountered. Be specific about files modified and tools used.',
          },
          {
            role: 'user',
            content: `Iteration ${iteration}:\n\nTools used: ${toolsUsed.join(', ') || 'none'}\nFiles modified: ${filesModified.join(', ') || 'none'}\n\nMessages:\n${messagesText.slice(0, 3000)}`,
          },
        ],
        maxOutputTokens: 200,
      });
      summary = result.text;
    } catch {
      // Fallback to simple summary
      summary = `Iteration ${iteration}: Used ${toolsUsed.length} tools (${toolsUsed.slice(0, 5).join(', ')}${toolsUsed.length > 5 ? '...' : ''}). Modified ${filesModified.length} files.`;
    }

    const iterationSummary: IterationSummary = {
      iteration,
      summary,
      toolsUsed: [...new Set(toolsUsed)],
      filesModified: [...new Set(filesModified)],
      estimatedTokens: estimateTokens(summary),
    };

    this.iterationSummaries.push(iterationSummary);
    return iterationSummary;
  }

  /**
   * Get summaries of previous iterations.
   */
  getIterationSummariesContext(): string {
    if (this.iterationSummaries.length === 0) {
      return '';
    }

    const header = '## Previous Iterations Summary\n\n';
    const summaries = this.iterationSummaries.map(s => 
      `### Iteration ${s.iteration}\n${s.summary}\n- Tools: ${s.toolsUsed.join(', ')}\n- Files: ${s.filesModified.join(', ') || 'none'}`
    ).join('\n\n');

    return header + summaries;
  }

  /**
   * Build context to inject into messages.
   * Call this before each iteration to get current context state.
   */
  buildContextInjection(): string {
    const parts: string[] = [];

    const summaries = this.getIterationSummariesContext();
    if (summaries) parts.push(summaries);

    const changeLog = this.getChangeLogContext();
    if (changeLog) parts.push(changeLog);

    // Note: File context is usually handled by tools, not injected
    // But we track it for budget management

    if (parts.length === 0) {
      return '';
    }

    return `\n\n---\n## Agent Context (Auto-managed)\n\n${parts.join('\n\n')}`;
  }

  /**
   * Prepare messages for a new iteration.
   * Compresses old iterations and manages context budget.
   */
  async prepareMessagesForIteration<TOOLS extends ToolSet>(
    currentMessages: ModelMessage[],
    iteration: number,
    model: LanguageModel,
    previousResult?: GenerateTextResult<TOOLS, never>
  ): Promise<{
    messages: ModelMessage[];
    summarized: boolean;
  }> {
    this.setIteration(iteration);

    // If first iteration or summarization disabled, return as-is
    if (iteration <= this.config.recentIterationsToKeep || !this.config.enableSummarization) {
      return { messages: currentMessages, summarized: false };
    }

    // Check if we need to summarize
    const totalTokens = currentMessages.reduce(
      (sum, m) => sum + estimateMessageTokens(m), 
      0
    );

    // Leave room for output and new content
    const targetBudget = this.config.maxContextTokens * 0.7;

    if (totalTokens < targetBudget) {
      return { messages: currentMessages, summarized: false };
    }

    // We need to compress! Summarize older iterations
    // Find the boundary between "old" and "recent" messages
    const messagesFromPreviousIteration = previousResult?.response.messages ?? [];

    if (messagesFromPreviousIteration.length > 0) {
      // Summarize the previous iteration
      await this.summarizeIteration(
        iteration - 1,
        messagesFromPreviousIteration,
        model
      );
    }

    // Keep only recent messages
    const recentStartIndex = Math.max(
      0, 
      currentMessages.length - (this.config.recentIterationsToKeep * 10) // Rough estimate: 10 messages per iteration
    );

    const recentMessages = currentMessages.slice(recentStartIndex);

    return {
      messages: recentMessages,
      summarized: true,
    };
  }

  /**
   * Evict least-recently-used files to stay within budget.
   */
  private evictFilesIfNeeded(newFileTokens: number): void {
    const currentFileTokens = Array.from(this.trackedFiles.values())
      .reduce((sum, f) => sum + f.estimatedTokens, 0);

    if (currentFileTokens + newFileTokens <= this.config.fileContextBudget) {
      return;
    }

    // Sort by last accessed (oldest first)
    const sorted = Array.from(this.trackedFiles.entries())
      .sort((a, b) => a[1].lastAccessed - b[1].lastAccessed);

    let tokensToFree = (currentFileTokens + newFileTokens) - this.config.fileContextBudget;

    for (const [path, file] of sorted) {
      if (tokensToFree <= 0) break;
      this.trackedFiles.delete(path);
      tokensToFree -= file.estimatedTokens;
    }
  }

  /**
   * Trim change log to stay within budget.
   */
  private trimChangeLog(): void {
    const currentTokens = this.changeLog
      .reduce((sum, e) => sum + estimateTokens(e.summary) + estimateTokens(e.details ?? ''), 0);

    if (currentTokens <= this.config.changeLogBudget) {
      return;
    }

    // Remove oldest entries
    while (this.changeLog.length > 0) {
      const tokens = this.changeLog
        .reduce((sum, e) => sum + estimateTokens(e.summary) + estimateTokens(e.details ?? ''), 0);
      if (tokens <= this.config.changeLogBudget) break;
      this.changeLog.shift();
    }
  }

  /**
   * Clear all tracked state.
   */
  clear(): void {
    this.trackedFiles.clear();
    this.changeLog = [];
    this.iterationSummaries = [];
    this.currentIteration = 0;
  }
}

/**
 * Create context-aware tool wrappers.
 * These wrap existing tools to track file operations.
 */
export function createContextAwareTools<TOOLS extends ToolSet>(
  tools: TOOLS,
  contextManager: RalphContextManager
): TOOLS {
  const wrapped: Record<string, unknown> = {};

  for (const [name, tool] of Object.entries(tools)) {
    if (name === 'readFile') {
      wrapped[name] = {
        ...tool,
        execute: async (args: { filePath?: string; path?: string; lineRange?: { start: number; end: number } }) => {
          const result = await (tool as any).execute(args);
          const path = args.filePath ?? args.path;

          if (result.success && result.content && path) {
            const tracked = contextManager.trackFileRead(path, result.content, {
              lineRange: args.lineRange,
            });
            return {
              ...result,
              content: tracked.content,
              truncated: tracked.truncated,
              totalLines: tracked.totalLines,
              lineRange: tracked.lineRange,
            };
          }
          return result;
        },
      };
    } else if (name === 'writeFile') {
      wrapped[name] = {
        ...tool,
        execute: async (args: { filePath?: string; path?: string; content: string }) => {
          const result = await (tool as any).execute(args);
          const path = args.filePath ?? args.path;

          if (result.success && path) {
            contextManager.trackFileWrite(path, args.content);
          }
          return result;
        },
      };
    } else if (name === 'editFile') {
      wrapped[name] = {
        ...tool,
        execute: async (args: { filePath?: string; path?: string; old_string: string; new_string: string }) => {
          const result = await (tool as any).execute(args);
          const path = args.filePath ?? args.path;

          if (result.success && path) {
            contextManager.trackFileEdit(path, args.old_string, args.new_string);
          }
          return result;
        },
      };
    } else {
      wrapped[name] = tool;
    }
  }

  return wrapped as TOOLS;
}

